/// Triangulates a polygon (optionally with holes) into a flat mesh at
/// z = 0, facing +z.
///
/// Panics:
/// Panics when triangulation fails (non-simple input).
///
/// Rust: `patterns::polygon_ops::polygon_to_mesh_2d`
#[pyfunction]
#[pyo3(name = "polygon_to_mesh_2d", signature = (poly, holes))]
pub fn pyfn_polygon_to_mesh_2d(poly: crate::generated::types::PyPolygon2, holes: Vec<crate::generated::types::PyPolygon2>) -> PyResult<crate::generated::types::PyMeshMesh> {
    let poly = poly.inner;
    let holes = holes.into_iter().map(|__e| __e.inner).collect::<Vec<_>>();
    let __r = crate::runtime::guard(|| rust_physics_engine::patterns::polygon_ops::polygon_to_mesh_2d(&poly, &holes));
    let __v = __r.map_err(crate::runtime::errors::InvalidArgumentError::new_err)?;
    Ok(crate::generated::types::PyMeshMesh { inner: __v })
}

